{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 도시공원 조례상 유효한 기후동행카드 소지 시 공원 입장료 감면 비율(퍼센트)",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 도시공원 조례 제20조 제2항 제2호는 기후동행카드 이용자 중 유효한 카드 소지자를 감면 대상으로 정하고 있다. 같은 항 본문은 그 감면 비율을 100분의 30 이상 100분의 50 이하의 범위에서 규칙이 정하는 바에 따라 감면할 수 있다고 규정한다. 따라서 조례가 직접 정한 감면 비율은 100분의 30 이상 100분의 50 이하이며, 구체적인 비율은 규칙이 정하는 바에 따른다.",
          "b_ids": "도시공원:제20조제2항, 도시공원:제20조제2항제2호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
